import (
	"fmt"
	"unsafe"
)

type AlignedMemoryBlock struct {
	AlignedPtr unsafe.Pointer
	Size       int
	rawBuf     []byte // Держит ссылку на память, чтобы GC не собрал ее
}

func AllocAlignedBlock(size int, alignment uintptr) *AlignedMemoryBlock {
	// Выделяем память с запасом для сдвига
	raw := make([]byte, size+int(alignment)-1)
	base := uintptr(unsafe.Pointer(&raw[0]))

	// Побитовое округление вверх до степени двойки
	aligned := (base + alignment - 1) &^ (alignment - 1)

	return &AlignedMemoryBlock{
		AlignedPtr: unsafe.Pointer(aligned),
		Size:       size,
		rawBuf:     raw,
	}
}

func main() {
	const (
		BlockSize = 4096
		Align64   = 64 // AVX-512 & 64B PCIe DMA boundary
	)

	fmt.Printf("=== Custom 64-Byte Aligned Allocator (AVX-512 & DMA) ===\n\n")

	// Тестируем 5 аллокаций
	for i := 1; i <= 5; i++ {
		block := AllocAlignedBlock(BlockSize, Align64)
		addr := uintptr(block.AlignedPtr)

		fmt.Printf("Block %d: Raw Addr: %p -> Aligned Addr: 0x%x (mod 64 = %d)\n",
			i, &block.rawBuf[0], addr, addr%Align64)

		if addr%Align64 != 0 {
			panic("Alignment violation!")
		}

		// Безопасное использование как слайс uint64
		u64Slice := unsafe.Slice((*uint64)(block.AlignedPtr), BlockSize/8)
		u64Slice[0] = 0xDEADBEEFCAFE
		fmt.Printf("  First uint64 value written cleanly: 0x%X\n", u64Slice[0])
	}

	fmt.Println("\nAll blocks are 100% aligned for AVX-512 and High-Speed NIC DMA!")
}

package main

import (
	"fmt"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

type CounterShard struct {
	val atomic.Uint64
	_   [56]byte // Cache line padding 64 bytes
}

type PerCPUCounter struct {
	shards []CounterShard
	mask   uint64
}

func NewPerCPUCounter(numShards int) *PerCPUCounter {
	// Округляем число шардов до ближайшей степени двойки для быстрой битовой маски
	p := 1
	for p < numShards {
		p <<= 1
	}

	return &PerCPUCounter{
		shards: make([]CounterShard, p),
		mask:   uint64(p - 1),
	}
}

func (c *PerCPUCounter) Add(delta uint64, workerID int) {
	idx := uint64(workerID) & c.mask
	c.shards[idx].val.Add(delta)
}

func (c *PerCPUCounter) Total() uint64 {
	var sum uint64
	for i := range c.shards {
		sum += c.shards[i].val.Load()
	}
	return sum
}

func main() {
	workers := runtime.NumCPU()
	runtime.GOMAXPROCS(workers)

	const totalOps uint64 = 40_000_000
	opsPerWorker := totalOps / uint64(workers)

	fmt.Printf("=== Global Atomic vs Per-CPU Counter (%d Cores, %d Ops) ===\n\n",
		workers, totalOps)

	// 1. Тест с единым глобальным атомиком (Высокая конкуренция шины)
	var globalCounter atomic.Uint64
	var wg1 sync.WaitGroup
	wg1.Add(workers)

	startGlobal := time.Now()
	for w := 0; w < workers; w++ {
		go func() {
			defer wg1.Done()
			for i := uint64(0); i < opsPerWorker; i++ {
				globalCounter.Add(1)
			}
		}()
	}
	wg1.Wait()
	durGlobal := time.Since(startGlobal)
	mopsGlobal := float64(totalOps) / durGlobal.Seconds() / 1_000_000
	fmt.Printf("Single Global Atomic: %v (%.2f Mops/s) [Result: %d]\n",
		durGlobal, mopsGlobal, globalCounter.Load())

	// 2. Тест с Per-CPU шардированным счетчиком
	perCPU := NewPerCPUCounter(workers)
	var wg2 sync.WaitGroup
	wg2.Add(workers)

	startPerCPU := time.Now()
	for w := 0; w < workers; w++ {
		workerID := w
		go func() {
			defer wg2.Done()
			for i := uint64(0); i < opsPerWorker; i++ {
				perCPU.Add(1, workerID)
			}
		}()
	}
	wg2.Wait()
	durPerCPU := time.Since(startPerCPU)
	mopsPerCPU := float64(totalOps) / durPerCPU.Seconds() / 1_000_000
	fmt.Printf("Per-CPU Padded Counter: %v (%.2f Mops/s) [Result: %d]\n",
		durPerCPU, mopsPerCPU, perCPU.Total())

	speedup := float64(durGlobal) / float64(durPerCPU)
	fmt.Printf("\nPer-CPU Architecture is %.2fx faster! Contention completely eliminated.\n", speedup)
}

